"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8902],{8902:(e,o,n)=>{n.d(o,{$p:()=>t,Q4:()=>i,Qe:()=>s,cQ:()=>a});let t=[{slug:"kataskevi-istoselidas",icon:"globe",nav:{el:"Κατασκευή Ιστοσελίδων",en:"Website Creation"},seo:{title:"Κατασκευή Ιστοσελίδων χωρίς Προκαταβολή | Advon Media",description:"Κατασκευή ιστοσελίδων για ελληνικές επιχειρήσεις: μοντέρνα, γρήγορη, δίγλωσση σελίδα χωρίς προκαταβολή — πληρώνετε μόνο τη φιλοξενία με το πρώτο δείγμα."},h1:{el:"Κατασκευή Ιστοσελίδων",en:"Website Creation"},pitch:{el:"Δεν πληρώνετε για υποσχέσεις. Πληρώνετε όταν δείτε τη σελίδα σας μπροστά σας — και τη φτιάχνουμε μαζί μέχρι να είναι δική σας.",en:"You don't pay for promises. You pay when you see your website in front of you — and we shape it together until it's truly yours."},pain:[{el:"Οι περισσότεροι επαγγελματίες ξέρουν ότι χρειάζονται ιστοσελίδα. Αυτό που τους κρατάει πίσω είναι πάντα τα ίδια: το κόστος που δεν ξέρεις πού θα καταλήξει, οι προκαταβολές πριν δεις οτιδήποτε, και ο φόβος ότι θα πληρώσεις για κάτι που τελικά δεν σου μοιάζει.",en:"Most professionals know they need a website. What holds them back is always the same: costs that spiral, deposits paid before seeing anything, and the fear of paying for something that ends up not feeling like you."},{el:"Γι’ αυτό δουλεύουμε ανάποδα. Πρώτα φτιάχνουμε τη σελίδα σας και σας τη δείχνουμε. Αν σας αρέσει, πληρώνετε μόνο τη φιλοξενία — και συνεχίζουμε τις αλλαγές μαζί, όσες χρειαστούν. Αν δεν σας αρέσει, δεν χάσατε τίποτα.",en:"That's why we work in reverse. First we build your website and show it to you. If you like it, you pay only the hosting — and we keep making changes together, as many as it takes. If you don't, you've lost nothing."},{el:"Και δεν φτιάχνουμε \xabένα site από πρότυπο\xbb. Η σελίδα σχεδιάζεται για το δικό σας επάγγελμα και τους δικούς σας πελάτες — δίγλωσση, γρήγορη, έτοιμη να βρεθεί στο Google.",en:"And we don't build “a site from a template”. Your page is designed for your profession and your clients — bilingual, fast, ready to be found on Google."}],steps:[{title:{el:"Μας στέλνετε το υλικό σας",en:"Send us your material"},body:{el:"Φωτογραφίες, λίγα βασικά κείμενα, τη λίστα των υπηρεσιών σας και τα στοιχεία επικοινωνίας. Αν έχετε δει κάποια ιστοσελίδα που σας άρεσε — δική μας ή οποιαδήποτε άλλη — στείλτε τη μας κι αυτή.",en:"Photos, a few short texts, your list of services and contact details. If you have seen a website you liked — ours or anyone else’s — send us that too."}},{title:{el:"Βλέπετε το πρώτο δείγμα",en:"See the first draft"},body:{el:"Μέσα σε 4–10 ημέρες σας παρουσιάζουμε την πρώτη έκδοση της σελίδας σας. Τότε μόνο εξοφλείται η φιλοξενία — καμία προκαταβολή πριν.",en:"Within 4–10 days we present the first version of your website. Only then is hosting settled — no deposit before that."}},{title:{el:"Αλλαγές μέχρι να είναι δική σας",en:"Changes until it feels yours"},body:{el:"Κάνουμε όσες αλλαγές χρειαστούν, χωρίς χρέωση — μέχρι η σελίδα να είναι ακριβώς όπως την έχετε στο μυαλό σας.",en:"We make as many changes as needed, free of charge — until the page is exactly how you imagined it."}},{title:{el:"Βγαίνετε στον αέρα",en:"You go live"},body:{el:"Αγοράζουμε το domain της επιλογής σας, ολοκληρώνουμε τις λεπτομέρειες και η σελίδα σας είναι online.",en:"We purchase the domain of your choice, wrap up the details and your website is online."}}],includes:[{el:"Μοντέρνα, γρήγορη, δίγλωσση ιστοσελίδα, φτιαγμένη για το δικό σας επάγγελμα — όχι ένα έτοιμο πρότυπο σαν όλα τα άλλα",en:"A modern, fast, bilingual website built for your profession — not an off-the-shelf template like all the rest"},{el:"Χωρίς προκαταβολή: πληρώνετε μόνο τη φιλοξενία με την παράδοση του πρώτου δείγματος",en:"No deposit: you pay only the hosting when the first draft is delivered"},{el:"Απεριόριστες αλλαγές μέχρι να γίνει ακριβώς όπως τη θέλετε",en:"Unlimited changes until it becomes exactly what you want"},{el:"Φιλοξενία, domain, ασφάλεια και αυτόματα backups — όλα σε ένα",en:"Hosting, domain, security and automatic backups — all in one"},{el:"Για μεγαλύτερες ανάγκες, πολυσέλιδη premium κατασκευή",en:"For bigger needs, multi-page premium builds"}],faqs:[{q:{el:"Πόσο κοστίζει η κατασκευή;",en:"How much does the build cost?"},a:{el:"Η κατασκευή είναι δωρεάν. Πληρώνετε μόνο τη φιλοξενία της σελίδας — και μόνο όταν παραδοθεί το πρώτο δείγμα. Καμία προκαταβολή, καμία κρυφή χρέωση.",en:"The build itself is free. You pay only for hosting — and only once the first draft is delivered. No deposit, no hidden fees."}},{q:{el:"Πόσο χρόνο παίρνει;",en:"How long does it take?"},a:{el:"Μόλις λάβουμε το υλικό σας, το πρώτο δείγμα παραδίδεται μέσα σε 4–10 ημέρες. Από εκεί, ο χρόνος εξαρτάται από τις αλλαγές που θα θελήσετε — συνεχίζουμε μέχρι να είστε απόλυτα ικανοποιημένοι.",en:"Once we receive your material, the first draft is delivered within 4–10 days. From there, timing depends on the changes you want — we keep going until you are fully happy."}},{q:{el:"Τι χρειάζεται να ετοιμάσω εγώ;",en:"What do I need to prepare?"},a:{el:"Λίγα πράγματα: φωτογραφίες, μερικά βασικά κείμενα για την επιχείρησή σας, τη λίστα των υπηρεσιών σας και τα στοιχεία επικοινωνίας. Αν δεν έχετε λογότυπο, σχεδιάζουμε εμείς ένα για εσάς.",en:"Just a few things: photos, some short texts about your business, your list of services and contact details. If you have no logo, we design one for you."}},{q:{el:"Τι γίνεται αν δεν μου αρέσει το αποτέλεσμα;",en:"What if I don't like the result?"},a:{el:"Το αλλάζουμε — όσες φορές χρειαστεί, χωρίς χρέωση, μέχρι να είναι ακριβώς όπως το θέλετε. Κι επειδή δεν έχετε δώσει προκαταβολή, δεν ρισκάρετε τίποτα για να δείτε το πρώτο δείγμα.",en:"We change it — as many times as needed, at no charge, until it's exactly what you want. And since there's no deposit, you risk nothing to see the first draft."}},{q:{el:"Μπορώ να σας δείξω μια ιστοσελίδα που μου αρέσει;",en:"Can I show you a website I like?"},a:{el:"Ναι, και μας βοηθάει πολύ. Στείλτε μας ένα link — μπορεί να είναι ιστοσελίδα άλλου επαγγελματία, ξένη, ή κάποια από το πορτφόλιό μας. Δεν την αντιγράφουμε, αλλά καταλαβαίνουμε αμέσως τι ύφος σας ταιριάζει και ξεκινάμε από εκεί.",en:"Yes, and it helps a lot. Send us a link — it can be another professional’s website, a foreign one, or one from our own portfolio. We do not copy it, but we immediately understand which style suits you and we start from there."}}],card:{points:[0,1],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"google-reviews-nfc",icon:"star",nav:{el:"Παρουσία στο Google",en:"Google Presence"},seo:{title:"Κριτικές Google & Προφίλ Επιχείρησης | Advon Media",description:"Περισσότερες κριτικές Google με NFC stand στον χώρο σας και πλήρες στήσιμο του προφίλ σας στο Google Maps: κατηγορίες, φωτογραφίες, ωράριο, απαντήσεις."},h1:{el:"Παρουσία στο Google",en:"Google Presence"},pitch:{el:"Στο Google δεν κερδίζει όποιος έχει την καλύτερη σελίδα — κερδίζει όποιος έχει τις περισσότερες πρόσφατες κριτικές. Το κάναμε για εμάς: 125+ κριτικές. Το ίδιο σύστημα, στημένο για εσάς.",en:"On Google, the winner isn't whoever has the best website — it's whoever has the most recent reviews. We did it for ourselves: 125+ reviews. The same system, set up for you."},pitch2:{el:"Πριν δουν τη σελίδα σας, οι πελάτες σάς βλέπουν στον χάρτη. Με τρεις φωτογραφίες και λάθος ωράριο, τους χάνετε πριν καν σας γνωρίσουν.",en:"Before they ever see your website, clients see you on the map. With three photos and the wrong opening hours, you lose them before they even meet you."},pain:[{el:"Όταν κάποιος ψάχνει \xabκομμωτήριο κοντά μου\xbb ή το όνομά σας, το πρώτο πράγμα που βλέπει δεν είναι η ιστοσελίδα σας — είναι το προφίλ σας στον χάρτη: τα αστέρια, οι φωτογραφίες, το ωράριο. Εκεί κρίνεται η πρώτη εντύπωση.",en:"When someone searches “hair salon near me” or your name, the first thing they see is not your website — it's your profile on the map: the stars, the photos, the opening hours. That is where the first impression is made."},{el:"Οι περισσότεροι ευχαριστημένοι πελάτες δεν αφήνουν ποτέ κριτική — όχι επειδή δεν θέλουν, αλλά επειδή θέλει ψάξιμο: να βρουν την επιχείρηση, να πατήσουν στο σωστό σημείο, να γράψουν. Μέχρι να φτάσουν σπίτι, το έχουν ξεχάσει.",en:"Most happy clients never leave a review — not because they don't want to, but because it takes effort: finding the business, tapping the right spot, typing. By the time they get home, they've forgotten."},{el:"Το NFC stand το λύνει επιτόπου: ο πελάτης ακουμπάει το κινητό του όσο είναι ακόμα μπροστά σας — και η φόρμα της κριτικής είναι ήδη ανοιχτή.",en:"The NFC stand solves it on the spot: the client taps their phone while they are still right in front of you — and the review form is already open."}],steps:[{title:{el:"Στήνουμε το προφίλ σας",en:"We set up your profile"},body:{el:"Πλήρες στήσιμο στο Google Maps: σωστές κατηγορίες, φωτογραφίες, ωράριο, περιγραφή — ώστε το προφίλ σας να δείχνει όπως σας αξίζει.",en:"Full Google Maps setup: correct categories, photos, opening hours, description — so your profile looks the way you deserve."}},{title:{el:"Τοποθετείτε το NFC stand",en:"Place the NFC stand"},body:{el:"Στο ταμείο, στη ρεσεψιόν ή στο γραφείο σας — εκεί όπου ο πελάτης σας ευχαριστεί φεύγοντας.",en:"At the register, the reception or your desk — right where your client thanks you on the way out."}},{title:{el:"Ο πελάτης ακουμπάει το κινητό",en:"The client taps their phone"},body:{el:"Η φόρμα της κριτικής ανοίγει αμέσως — και η κριτική είναι θέμα δευτερολέπτων. Σας δίνουμε και έτοιμα μηνύματα για να το ζητάτε φυσικά.",en:"The review form opens instantly — leaving a review takes seconds. We also give you ready-made messages so asking feels natural."}},{title:{el:"Απαντάμε σε κάθε κριτική",en:"We answer every review"},body:{el:"Κάθε κριτική παίρνει επαγγελματική απάντηση — γιατί το προφίλ που απαντά δείχνει επιχείρηση που νοιάζεται.",en:"Every review gets a professional reply — because a profile that responds shows a business that cares."}}],includes:[{el:"NFC stand για τον χώρο σας: ο πελάτης απλώς ακουμπάει το κινητό του — και η κριτική είναι θέμα δευτερολέπτων",en:"An NFC stand for your space: the client simply taps their phone — and the review takes seconds"},{el:"Έτοιμα μηνύματα για τους πελάτες σας και επαγγελματική απάντηση σε κάθε κριτική",en:"Ready-made messages for your clients and a professional reply to every review"},{el:"Πλήρες στήσιμο του προφίλ σας στο Google Maps: σωστές κατηγορίες, φωτογραφίες, ωράριο, περιγραφή",en:"Full setup of your Google Maps profile: correct categories, photos, opening hours, description"}],faqs:[{q:{el:"Τι είναι το NFC stand και πώς λειτουργεί;",en:"What is the NFC stand and how does it work?"},a:{el:"Είναι μια κομψή βάση για τον χώρο σας, με την ίδια τεχνολογία που χρησιμοποιείτε στις ανέπαφες πληρωμές. Ο πελάτης ακουμπάει το κινητό του και ανοίγει αμέσως η φόρμα κριτικής της επιχείρησής σας στο Google. Έχει και QR code για παλαιότερες συσκευές.",en:"It's an elegant stand for your space, using the same technology as contactless payments. The client taps their phone and your business's Google review form opens instantly. It also has a QR code for older devices."}},{q:{el:"Λειτουργεί με iPhone και Android;",en:"Does it work with iPhone and Android?"},a:{el:"Ναι — με iPhone (iOS 13 και νεότερα) και με κάθε Android που έχει NFC. Για παλαιότερες συσκευές υπάρχει το QR code ως εναλλακτική.",en:"Yes — with iPhone (iOS 13 and newer) and any Android with NFC. For older devices, the QR code works as a backup."}},{q:{el:"Οι κριτικές είναι πραγματικές;",en:"Are the reviews genuine?"},a:{el:"Απολύτως. Οι κριτικές γράφονται από τους δικούς σας πελάτες, με τους δικούς τους λογαριασμούς Google. Το stand απλώς αφαιρεί τον κόπο — δεν γράφει κριτικές, κάνει εύκολο για τους ευχαριστημένους πελάτες σας να τις αφήσουν.",en:"Absolutely. Reviews are written by your own clients, from their own Google accounts. The stand simply removes the friction — it doesn't write reviews, it makes it easy for your happy clients to leave them."}},{q:{el:"Δεν έχω προφίλ στο Google Maps. Μπορείτε να το φτιάξετε;",en:"I don't have a Google Maps profile. Can you create it?"},a:{el:"Ναι. Αν δεν υπάρχει προφίλ, το δημιουργούμε από την αρχή\xb7 αν υπάρχει, το διορθώνουμε και το ολοκληρώνουμε: κατηγορίες, φωτογραφίες, ωράριο, περιγραφή — όλα όπως πρέπει.",en:"Yes. If there's no profile, we create it from scratch; if there is one, we fix and complete it: categories, photos, opening hours, description — everything as it should be."}}],card:{points:[0,2],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"online-rantevou",icon:"calendar",showPrices:!0,nav:{el:"Online Ραντεβού",en:"Online Booking"},seo:{title:"Σύστημα Online Ραντεβού για Επιχειρήσεις | Advon Media",description:"Σύστημα online ραντεβού: δική σας σελίδα κρατήσεων, ημερολόγιο συγχρονισμένο με το δικό σας, αυτόματες υπενθυμίσεις. Από 5€/μήνα για έναν επαγγελματία."},h1:{el:"Online Ραντεβού",en:"Online Appointments"},pitch:{el:"Πόσα ραντεβού σάς ζητούν το βράδυ, την Κυριακή, ή την ώρα που είστε με πελάτη; Όσα δεν προλαβαίνετε εσείς, τα κλείνει η σελίδα σας.",en:"How many appointments are requested at night, on Sundays, or while you're with a client? The ones you can't get to, your page books for you."},pain:[{el:"Τα περισσότερα αιτήματα για ραντεβού δεν έρχονται μέσα στο ωράριό σας. Έρχονται το βράδυ, την Κυριακή, την ώρα που έχετε πελάτη και δεν μπορείτε να σηκώσετε το τηλέφωνο. Κάποιοι θα ξαναπάρουν. Οι περισσότεροι όχι.",en:"Most appointments aren't requested during your working hours. They're requested at night, on Sundays, while you're with a client and can't pick up the phone. Some will call again. Most won't."},{el:"Και όσα κλείνονται, θέλουν διαχείριση: τηλέφωνα, μηνύματα, \xabτελικά μπορώ Πέμπτη;\xbb, ακυρώσεις τελευταίας στιγμής, ραντεβού που ξεχάστηκαν. Δικός σας χρόνος, κάθε μέρα.",en:"And the ones that do get booked need managing: calls, messages, “actually, can I do Thursday?”, last-minute cancellations, forgotten appointments. Your time, every single day."},{el:"Μια σελίδα κρατήσεων τα αναλαμβάνει όλα αυτά: ο πελάτης βλέπει τις διαθέσιμες ώρες και κλείνει μόνος του — κι εσείς απλώς βλέπετε το ημερολόγιο να γεμίζει.",en:"A booking page takes all of that on: the client sees the available times and books on their own — and you simply watch the calendar fill up."}],steps:[{title:{el:"Στήνουμε τη σελίδα κρατήσεων",en:"We set up your booking page"},body:{el:"Με τις υπηρεσίες σας σε λίστα, τις διάρκειες και το ωράριό σας — καθαρή, όμορφη, στα χρώματά σας.",en:"With your services in a list, durations and your schedule — clean, beautiful, in your colors."}},{title:{el:"Τη συνδέουμε με το ημερολόγιό σας",en:"We connect it to your calendar"},body:{el:"Όλα τα ραντεβού σε ένα ημερολόγιο, συγχρονισμένο με το δικό σας — ό,τι κλείνεται online φαίνεται αμέσως.",en:"All appointments in one calendar, synced with your own — whatever is booked online shows up instantly."}},{title:{el:"Μοιράζεστε το link σας",en:"Share your link"},body:{el:"Στην ιστοσελίδα σας, στο Instagram, στο προφίλ σας στο Google — όπου σας βρίσκουν οι πελάτες σας.",en:"On your website, your Instagram, your Google profile — wherever your clients find you."}},{title:{el:"Οι πελάτες κλείνουν μόνοι τους",en:"Clients book on their own"},body:{el:"Από το κινητό, σε δευτερόλεπτα, όποια ώρα θέλουν. Και οι αυτόματες υπενθυμίσεις φροντίζουν να μην \xabξεχαστεί\xbb κανένα ραντεβού.",en:"From their phone, in seconds, any time they like. Automatic reminders make sure no appointment gets “forgotten”."}}],includes:[{el:"Αυτόματη υπενθύμιση με email πριν από κάθε ραντεβού — λιγότερες ακυρώσεις, λιγότερα κενά στο πρόγραμμα",en:"Automatic email reminder before every appointment — fewer cancellations, fewer gaps in your schedule"},{el:"Δική σας σελίδα κρατήσεων — καθαρή, όμορφη, ξεχωριστή: ο πελάτης βλέπει τις υπηρεσίες σας σε λίστα, διαλέγει ώρα και κλείνει σε δευτερόλεπτα, από το κινητό",en:"Your own booking page — clean, beautiful, distinct: the client sees your services in a list, picks a time and books in seconds, from their phone"},{el:"Εξίσου απλή για εσάς: όλα τα ραντεβού σε ένα ημερολόγιο, συγχρονισμένο με το δικό σας",en:"Just as simple for you: all appointments in one calendar, synced with your own"},{el:"Για ομάδες (κομμωτήρια, barbershops, ιατρεία): κάθε πελάτης κλείνει στον δικό του επαγγελματία",en:"For teams (hair salons, barbershops, clinics): every client books with their own professional"},{el:"Από 5€/μήνα για έναν επαγγελματία \xb7 15–25€/μήνα για ομάδες, ανάλογα με τα άτομα",en:"From €5/month for one professional \xb7 €15–25/month for teams, depending on team size"}],faqs:[{q:{el:"Πόσο κοστίζει;",en:"How much does it cost?"},a:{el:"Από 5€/μήνα για έναν επαγγελματία. Για ομάδες — κομμωτήρια, barbershops, ιατρεία — από 15 έως 25€/μήνα, ανάλογα με τα άτομα.",en:"From €5/month for one professional. For teams — hair salons, barbershops, clinics — from €15 to €25/month, depending on team size."}},{q:{el:"Χρειάζεται ο πελάτης μου να κατεβάσει εφαρμογή;",en:"Does my client need to download an app?"},a:{el:"Όχι. Η σελίδα κρατήσεων ανοίγει στον browser του κινητού — ο πελάτης διαλέγει υπηρεσία, ώρα, και κλείνει. Τίποτα να εγκαταστήσει, τίποτα να θυμάται.",en:"No. The booking page opens in the phone browser — the client picks a service, a time, and books. Nothing to install, nothing to remember."}},{q:{el:"Συγχρονίζεται με το ημερολόγιο που ήδη χρησιμοποιώ;",en:"Does it sync with the calendar I already use?"},a:{el:"Ναι. Όλα τα ραντεβού μαζεύονται σε ένα ημερολόγιο, συγχρονισμένο με το δικό σας — δεν χρειάζεται να κοιτάτε δύο μέρη.",en:"Yes. All appointments gather in one calendar, synced with yours — you never have to check two places."}},{q:{el:"Είμαστε ομάδα — ο καθένας με τους πελάτες του. Καλύπτεται;",en:"We're a team — each of us has our own clients. Is that covered?"},a:{el:"Ναι, είναι από τα πιο συχνά σενάρια: κάθε πελάτης κλείνει στον δικό του επαγγελματία, και ο καθένας βλέπει το δικό του πρόγραμμα.",en:"Yes, it is one of the most common setups: every client books with their own professional, and each of you sees your own schedule."}}],card:{points:[0,1],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"ai-voithos",icon:"bot",nav:{el:"AI Βοηθός Ιστοσελίδας",en:"Website AI Assistant"},seo:{title:"AI Βοηθός για Ιστοσελίδες — Chatbot στα Ελληνικά | Advon",description:"AI βοηθός (chatbot) για την ιστοσελίδα σας: απαντά σε ωράριο, υπηρεσίες και συχνές ερωτήσεις στα ελληνικά και αγγλικά — και σας στέλνει όνομα και τηλέφωνο."},h1:{el:"AI Βοηθός Ιστοσελίδας",en:"Website AI Assistant"},pitch:{el:"Οι περισσότεροι επισκέπτες μπαίνουν στη σελίδα σας όταν εσείς δεν μπορείτε να απαντήσετε. Κάθε ερώτηση που μένει αναπάντητη είναι χαμένη δουλειά — από εδώ και πέρα, κανένας δεν φεύγει χωρίς απάντηση.",en:"Most visitors land on your website when you can't answer. Every unanswered question is lost business — from now on, no one leaves without an answer."},pain:[{el:"Κάθε ερώτηση που μένει αναπάντητη είναι, τις περισσότερες φορές, ένας πελάτης που παίρνει τον επόμενο στη λίστα. Όχι επειδή διάλεξε άλλον — επειδή ο άλλος απάντησε πρώτος.",en:"Every question left unanswered is, more often than not, a client calling the next name on the list. Not because they chose someone else — because someone else answered first."},{el:"Ο AI βοηθός μαθαίνει την επιχείρησή σας — υπηρεσίες, ωράριο, συχνές ερωτήσεις — και απαντά στη στιγμή, όλο το 24ωρο, στα ελληνικά και στα αγγλικά. Κι όταν κάποιος ενδιαφέρεται, σας στέλνει το όνομα και το τηλέφωνό του.",en:"The AI assistant learns your business — services, hours, common questions — and answers instantly, around the clock, in Greek and English. And when someone is interested, it sends you their name and phone number."}],steps:[{title:{el:"Μας δίνετε τις πληροφορίες",en:"You give us the information"},body:{el:"Υπηρεσίες, ωράριο, συχνές ερωτήσεις — ή τις αντλούμε κατευθείαν από την ιστοσελίδα σας.",en:"Services, opening hours, common questions — or we pull them straight from your website."}},{title:{el:"Εκπαιδεύουμε τον βοηθό",en:"We train the assistant"},body:{el:"Μαθαίνει την επιχείρησή σας και απαντά με τον δικό σας τόνο — όχι σαν ρομπότ.",en:"It learns your business and answers in your tone — not like a robot."}},{title:{el:"Τον ενσωματώνουμε στη σελίδα σας",en:"We embed it on your site"},body:{el:"Ένα διακριτικό εικονίδιο συνομιλίας, κάτω δεξιά — έτοιμο να απαντήσει σε κάθε επισκέπτη.",en:"A discreet chat icon, bottom right — ready to answer every visitor."}},{title:{el:"Σας στέλνει τους ενδιαφερόμενους",en:"It sends you the leads"},body:{el:"Όταν κάποιος θέλει να προχωρήσει, ο βοηθός ζητά όνομα και τηλέφωνο — και σας τα προωθεί.",en:"When someone wants to move forward, the assistant asks for a name and phone number — and forwards them to you."}}],includes:[{el:"Απαντά στη στιγμή σε ωράριο, υπηρεσίες και συχνές ερωτήσεις — στα ελληνικά και στα αγγλικά",en:"Answers instantly about hours, services and common questions — in Greek and English"},{el:"Όταν κάποιος ενδιαφέρεται, σας στέλνει όνομα και τηλέφωνο",en:"When someone is interested, it sends you their name and phone number"},{el:"Δουλεύει όλο το 24ωρο — και τις ώρες που εσείς δεν μπορείτε",en:"Works around the clock — including the hours you cannot"},{el:"Δοκιμάστε τον τώρα — είναι κάτω δεξιά σε αυτή τη σελίδα",en:"Try it right now — it is at the bottom right of this page"}],faqs:[{q:{el:"Σε τι μπορεί να απαντήσει;",en:"What can it answer?"},a:{el:"Σε ό,τι του μάθουμε για την επιχείρησή σας: ωράριο, υπηρεσίες, τοποθεσία, τρόπους επικοινωνίας, συχνές ερωτήσεις των πελατών σας. Όσο πιο πλήρεις οι πληροφορίες, τόσο πιο χρήσιμος γίνεται.",en:"Anything we teach it about your business: opening hours, services, location, ways to reach you, your clients' most common questions. The more complete the information, the more useful it becomes."}},{q:{el:"Μιλάει και αγγλικά;",en:"Does it speak English too?"},a:{el:"Ναι — απαντά στα ελληνικά και στα αγγλικά, ανάλογα με τη γλώσσα στην οποία γράφει ο επισκέπτης.",en:"Yes — it answers in Greek and in English, matching the language the visitor writes in."}},{q:{el:"Πώς μαθαίνω ποιος ενδιαφέρθηκε;",en:"How do I find out who was interested?"},a:{el:"Όταν ένας επισκέπτης θέλει να προχωρήσει — να κλείσει ραντεβού, να ρωτήσει για τιμή, να τον καλέσετε — ο βοηθός του ζητά όνομα και τηλέφωνο και σας τα στέλνει.",en:"When a visitor wants to move forward — book an appointment, ask about pricing, get a call back — the assistant asks for their name and phone number and sends them to you."}},{q:{el:"Μπορώ να τον δοκιμάσω πριν αποφασίσω;",en:"Can I try it before deciding?"},a:{el:"Ναι — τον χρησιμοποιούμε κι εμείς οι ίδιοι. Είναι το εικονίδιο συνομιλίας κάτω δεξιά σε αυτή τη σελίδα: ρωτήστε τον ό,τι θέλετε για την Advon.",en:"Yes — we use it ourselves. It is the chat icon at the bottom right of this page: ask it anything about Advon."}}],card:{points:[0,1],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"direct-booking",icon:"building",nav:{el:"Direct Booking για Τουρισμό",en:"Direct Booking for Tourism"},seo:{title:"Ιστοσελίδα Ξενοδοχείου με Κρατήσεις χωρίς Προμήθειες",description:"Direct booking για ξενοδοχεία, ενοικιαζόμενα και βίλες: premium ιστοσελίδα με δική σας μηχανή κρατήσεων, συγχρονισμός με Booking και Airbnb, χωρίς προμήθειες."},h1:{el:"Direct Booking για Τουρισμό",en:"Direct Booking for Tourism"},sub:{el:"Για ξενοδοχεία, ενοικιαζόμενα διαμερίσματα και βίλες.",en:"For hotels, rental apartments and villas."},pitch:{el:"Η προμήθεια από μία και μόνο κράτηση συχνά κοστίζει όσο ολόκληρος ο μήνας μαζί μας.",en:"The commission from a single booking often costs as much as a whole month with us."},pain:[{el:"Κάθε κράτηση που έρχεται από τις πλατφόρμες αφήνει ένα ποσοστό πίσω της. Στο τέλος της σεζόν, αυτά τα ποσοστά γίνονται ένα σοβαρό ποσό — λεφτά που δουλέψατε εσείς και κράτησε η πλατφόρμα.",en:"Every booking that comes through the platforms leaves a percentage behind. By the end of the season, those percentages add up to serious money — money you worked for and the platform kept."},{el:"Δεν χρειάζεται να φύγετε από το Booking ή το Airbnb — εκεί σας ανακαλύπτουν. Χρειάζεται όμως οι επισκέπτες που σας ψάχνουν με το όνομά σας να μπορούν να κλείσουν απευθείας σε εσάς, χωρίς μεσάζοντα.",en:"You don't need to leave Booking or Airbnb — that's where people discover you. But guests who search for you by name should be able to book directly with you, without a middleman."},{el:"Με δική σας μηχανή κρατήσεων και ένα κοινό ημερολόγιο συγχρονισμένο με όλες τις πλατφόρμες, κάθε απευθείας κράτηση είναι εξ ολοκλήρου δική σας — και διπλοκράτηση δεν υπάρχει.",en:"With your own booking engine and one calendar synced across all platforms, every direct booking is entirely yours — and double bookings simply cannot happen."}],steps:[{title:{el:"Φτιάχνουμε την premium σελίδα σας",en:"We build your premium site"},body:{el:"Μια ιστοσελίδα αντάξια του καταλύματός σας — φωτογραφίες, δωμάτια, τοποθεσία, όλα όπως πρέπει.",en:"A website worthy of your property — photos, rooms, location, everything as it should be."}},{title:{el:"Στήνουμε τη μηχανή κρατήσεων",en:"We set up the booking engine"},body:{el:"Ο επισκέπτης βλέπει διαθεσιμότητα και κλείνει απευθείας σε εσάς — χωρίς προμήθειες σε τρίτους.",en:"Guests see availability and book directly with you — no commissions to third parties."}},{title:{el:"Συγχρονίζουμε με τις πλατφόρμες",en:"We sync with the platforms"},body:{el:"Booking, Airbnb, Expedia: ένα ημερολόγιο για όλα, καμία διπλοκράτηση.",en:"Booking, Airbnb, Expedia: one calendar for everything, zero double bookings."}},{title:{el:"Βλέπετε τι γλιτώσατε",en:"You see what you saved"},body:{el:"Κάθε μήνα λαμβάνετε αναφορά με τις προμήθειες που θα είχατε πληρώσει — και δεν πληρώσατε.",en:"Every month you receive a report of the commissions you would have paid — and didn't."}}],includes:[{el:"Premium ιστοσελίδα με δική σας μηχανή κρατήσεων — χωρίς προμήθειες",en:"A premium website with your own booking engine — no commissions"},{el:"Συγχρονισμός με Booking, Airbnb, Expedia: ένα ημερολόγιο, καμία διπλοκράτηση",en:"Sync with Booking, Airbnb, Expedia: one calendar, no double bookings"},{el:"Κάθε μήνα, αναφορά με τις προμήθειες που γλιτώσατε",en:"Every month, a report of the commissions you saved"},{el:"Extras: κινηματογραφικό βίντεο ακινήτου, επιπλέον γλώσσες (DE/FR/IT)",en:"Extras: cinematic property video, additional languages (DE/FR/IT)"}],faqs:[{q:{el:"Πρέπει να σταματήσω το Booking και το Airbnb;",en:"Do I have to stop using Booking and Airbnb?"},a:{el:"Όχι — συνεχίζουν κανονικά. Οι πλατφόρμες σάς φέρνουν νέους επισκέπτες\xb7 η δική σας σελίδα φροντίζει όσοι σας ψάχνουν με το όνομά σας να κλείνουν απευθείας, χωρίς προμήθεια.",en:"No — they keep running as usual. The platforms bring you new guests; your own site makes sure those searching for you by name book directly, commission-free."}},{q:{el:"Πώς αποφεύγονται οι διπλοκρατήσεις;",en:"How are double bookings avoided?"},a:{el:"Το ημερολόγιο της σελίδας σας συγχρονίζεται με Booking, Airbnb και Expedia. Όταν ένα δωμάτιο κλείνει οπουδήποτε, κλείνει παντού — αυτόματα.",en:"Your site's calendar syncs with Booking, Airbnb and Expedia. When a room is booked anywhere, it closes everywhere — automatically."}},{q:{el:"Πληρώνω προμήθεια στις απευθείας κρατήσεις;",en:"Do I pay commission on direct bookings?"},a:{el:"Όχι. Οι κρατήσεις από τη δική σας σελίδα γίνονται χωρίς προμήθειες. Και κάθε μήνα βλέπετε στην αναφορά σας πόσα θα είχαν κρατήσει οι πλατφόρμες για τις ίδιες κρατήσεις.",en:"No. Bookings made through your own site carry no commissions. And every month, your report shows what the platforms would have kept for those same bookings."}},{q:{el:"Σε ποιες γλώσσες μπορεί να είναι η σελίδα;",en:"What languages can the site be in?"},a:{el:"Ελληνικά και αγγλικά ως βάση — και προαιρετικά γερμανικά, γαλλικά ή ιταλικά, ανάλογα με το κοινό σας.",en:"Greek and English as standard — with optional German, French or Italian, depending on your guests."}}],card:{points:[0,1],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"psifiako-menou-qr",icon:"qr",nav:{el:"Ψηφιακό Μενού QR",en:"QR Digital Menu"},seo:{title:"Ψηφιακό Μενού QR για Εστίαση & Καφέ | Advon Media",description:"Ψηφιακό μενού QR: δίγλωσσος κατάλογος που ανοίγει με ένα σκανάρισμα, με φωτογραφίες και αλλεργιογόνα. Αλλάζετε τιμές και πιάτα σε λίγα λεπτά, όποτε θέλετε."},h1:{el:"Ψηφιακό Μενού QR",en:"QR Digital Menu"},pitch:{el:"Πόσο κόστισε η τελευταία επανεκτύπωση καταλόγων; Αυτή ήταν και η τελευταία.",en:"How much did the last menu reprint cost? That was also the last one."},pain:[{el:"Κάθε αλλαγή τιμής σημαίνει νέα εκτύπωση — ή διορθώσεις με στυλό πάνω στον κατάλογο, μπροστά στον πελάτη. Και κάθε καινούργιο πιάτο περιμένει την επόμενη παραγγελία στο τυπογραφείο για να μπει στον κατάλογο.",en:"Every price change means a new print run — or pen corrections on the menu, right in front of the customer. And every new dish waits for the next print order to exist."},{el:"Με το ψηφιακό μενού, ο κατάλογος ζει στο κινητό του πελάτη: σκανάρει το QR στο τραπέζι και τον βλέπει στη γλώσσα του, με φωτογραφίες και με τα αλλεργιογόνα καθαρά σημειωμένα.",en:"With a digital menu, the catalog lives on the customer's phone: they scan the QR at the table and see it in their language, with photos and allergens clearly marked."},{el:"Κι εσείς αλλάζετε τιμές και πιάτα σε λίγα λεπτά, όποτε θέλετε — χωρίς τυπογραφείο, χωρίς αναμονή.",en:"And you change prices and dishes in minutes, whenever you like — no print shop, no waiting."}],steps:[{title:{el:"Μας στέλνετε τον κατάλογό σας",en:"Send us your menu"},body:{el:"Όπως τον έχετε — έντυπο, PDF ή απλή λίστα. Αναλαμβάνουμε εμείς τα υπόλοιπα.",en:"As you have it — printed, PDF or a simple list. We take it from there."}},{title:{el:"Τον στήνουμε ψηφιακά",en:"We build it digitally"},body:{el:"Δίγλωσσος, με φωτογραφίες και αλλεργιογόνα, οργανωμένος σε κατηγορίες — έτοιμος να ανοίξει με ένα σκανάρισμα.",en:"Bilingual, with photos and allergens, organized in categories — ready to open with a single scan."}},{title:{el:"Τοποθετείτε τα QR στα τραπέζια",en:"Place the QR codes on the tables"},body:{el:"Σας παραδίδουμε τα QR έτοιμα για εκτύπωση — για τραπέζια, βιτρίνα ή stand.",en:"We deliver the QR codes print-ready — for tables, your storefront or a stand."}},{title:{el:"Αλλάζετε ό,τι θέλετε, όποτε θέλετε",en:"Change anything, anytime"},body:{el:"Τιμές, πιάτα, φωτογραφίες — οι αλλαγές γίνονται σε λίγα λεπτά και εμφανίζονται αμέσως.",en:"Prices, dishes, photos — changes take minutes and appear instantly."}}],includes:[{el:"Δίγλωσσο μενού που ανοίγει με ένα σκανάρισμα — με φωτογραφίες και αλλεργιογόνα",en:"A bilingual menu that opens with one scan — with photos and allergens"},{el:"Αλλάζετε τιμές και πιάτα σε λίγα λεπτά, όποτε θέλετε",en:"Change prices and dishes in minutes, whenever you want"},{el:"QR codes έτοιμα για εκτύπωση — για τραπέζια, βιτρίνα ή stand",en:"Print-ready QR codes — for tables, storefront or stand"}],faqs:[{q:{el:"Χρειάζεται ο πελάτης να κατεβάσει κάτι;",en:"Does the customer need to download anything?"},a:{el:"Όχι. Σκανάρει το QR με την κάμερα του κινητού του και το μενού ανοίγει στον browser — σε ένα-δύο δευτερόλεπτα.",en:"No. They scan the QR with their phone camera and the menu opens in the browser — within a second or two."}},{q:{el:"Πόσο εύκολα αλλάζω τιμές ή πιάτα;",en:"How easily can I change prices or dishes?"},a:{el:"Σε λίγα λεπτά, όποτε το χρειαστείτε — και οι αλλαγές εμφανίζονται αμέσως σε όλα τα τραπέζια. Τα QR δεν αλλάζουν ποτέ, οπότε δεν ξανατυπώνετε τίποτα.",en:"In a few minutes, whenever you need — and changes appear instantly on every table. The QR codes themselves never change, so you never reprint anything."}},{q:{el:"Σε ποιες γλώσσες είναι το μενού;",en:"What languages is the menu in?"},a:{el:"Ελληνικά και αγγλικά — ο πελάτης το βλέπει στη γλώσσα του, κάτι που για τουριστικές περιοχές κάνει τεράστια διαφορά.",en:"Greek and English — customers see it in their own language, which makes a huge difference in tourist areas."}},{q:{el:"Καλύπτονται τα αλλεργιογόνα;",en:"Are allergens covered?"},a:{el:"Ναι — κάθε πιάτο μπορεί να έχει σημειωμένα τα αλλεργιογόνα του, ώστε ο πελάτης να βρίσκει την πληροφορία χωρίς να χρειάζεται να ρωτήσει.",en:"Yes — every dish can list its allergens, so customers find the information without having to ask."}}],card:{points:[0,1],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}},{slug:"custom-logismiko",icon:"code",nav:{el:"Custom Μικρό Λογισμικό",en:"Custom Small Software"},seo:{title:"Custom Πρόγραμμα για Επιχειρήσεις | Advon Media",description:"Custom πρόγραμμα φτιαγμένο για τον τρόπο που δουλεύει η επιχείρησή σας — όχι έτοιμο CRM. Στο κινητό και στον υπολογιστή, με τα δεδομένα σας περασμένα."},h1:{el:"Custom Μικρό Λογισμικό",en:"Custom Small Software"},pitch:{el:"Αυτό που βλέπετε στο demo δεν είναι μακέτα — είναι το πραγματικό σύστημα που τρέχει καθημερινά την Advon, φτιαγμένο ακριβώς όπως ονειρευόμασταν να δείχνει η δουλειά μας. Το ίδιο χτίζουμε και για εσάς, γύρω από τον δικό σας τρόπο δουλειάς.",en:"What you see in the demo isn't a mockup — it's the real system that runs Advon every day, built exactly as we dreamed our own work should look. We build the same for you, around the way you actually work."},pain:[{el:"Ραντεβού σε τετράδιο, πελάτες στο Excel, παραγγελίες στο Viber — και η πραγματική εικόνα της δουλειάς, στο μυαλό σας. Όσο μεγαλώνει η δουλειά, τόσο πιο συχνά κάτι ξεφεύγει.",en:"Appointments in a notebook, clients in Excel, orders on Viber — and the real picture of the business, in your head. The more the work grows, the more often something slips."},{el:"Υπάρχουν χίλια έτοιμα εργαλεία και CRM — κανένα δεν δουλεύει όπως δουλεύετε εσείς. Έρχονται με τους δικούς τους κανόνες: εκατό λειτουργίες που δεν χρειάζεστε, και οι πέντε που χρειάζεστε, κρυμμένες σε λάθος μενού.",en:"There are a thousand ready-made tools and CRMs — none of them works the way you do. They come with their own rules: a hundred features you don't need, and the five you do need, hidden in the wrong menu."},{el:"Γι’ αυτό φτιάξαμε το δικό μας πρόγραμμα για την Advon, κι ας υπήρχαν παρόμοια: κάθε εργασία γίνεται πλέον στον μισό χρόνο. Το ίδιο μπορούμε να φτιάξουμε και για εσάς — γύρω από τον δικό σας τρόπο δουλειάς.",en:"That's why we built our own software for Advon, even though similar tools existed: every task now takes half the time. We can build the same for you — around the way you actually work."}],steps:[{title:{el:"Μας δείχνετε πώς δουλεύετε",en:"Show us how you work"},body:{el:"Τα τετράδια, τα Excel, τις ροές της ημέρας σας — καταλαβαίνουμε πρώτα τη δουλειά, μετά σχεδιάζουμε.",en:"Your notebooks, your spreadsheets, your daily flows — we understand the work first, then we design."}},{title:{el:"Σχεδιάζουμε μαζί",en:"We design it together"},body:{el:"Κάθε καρτέλα και κάθε κουμπί μπαίνει εκεί που θα το ψάχνατε — γιατί το σχεδιάζετε μαζί μας.",en:"Every tab and every button goes exactly where you would look for it — because you design it with us."}},{title:{el:"Το χτίζουμε και περνάμε τα δεδομένα σας",en:"We build it and migrate your data"},body:{el:"Παίρνουμε τα Excel και τα τετράδιά σας και τα περνάμε εμείς — ξεκινάτε με όλα στη θέση τους.",en:"We take your spreadsheets and notebooks and migrate them ourselves — you start with everything in place."}},{title:{el:"Εκπαιδεύουμε την ομάδα σας",en:"We train your team"},body:{el:"Στο κινητό και στον υπολογιστή, όλοι ξέρουν τι να πατήσουν από την πρώτη μέρα.",en:"On mobile and desktop, everyone knows what to press from day one."}}],includes:[{el:"Το πρόγραμμα των ονείρων σας — όπως ακριβώς θα το σχεδιάζατε εσείς, αν μπορούσατε: κάθε καρτέλα, κάθε κουμπί, εκεί που θα το ψάχνατε",en:"The software of your dreams — exactly as you would design it, if you could: every tab, every button, right where you would look for it"},{el:"Στο κινητό και στον υπολογιστή, με τα δεδομένα σας περασμένα από εμάς και εκπαίδευση της ομάδας σας",en:"On mobile and desktop, with your data migrated by us and your team trained"},{el:"Για επιχειρήσεις που πνίγονται σε Excel, τετράδια και Viber",en:"For businesses drowning in Excel, notebooks and Viber"},{el:"Φτιάξαμε το δικό μας για την Advon, κι ας υπήρχαν παρόμοια: κάθε εργασία γίνεται πλέον στον μισό χρόνο",en:"We built our own for Advon, even though similar tools existed: every task now takes half the time"}],faqs:[{q:{el:"Σε τι διαφέρει από ένα έτοιμο CRM;",en:"How is it different from a ready-made CRM?"},a:{el:"Ένα έτοιμο CRM σας ζητά να προσαρμοστείτε εσείς σε αυτό. Το custom πρόγραμμα χτίζεται γύρω από τον τρόπο που ήδη δουλεύετε: έχει μόνο ό,τι χρειάζεστε, εκεί που θα το ψάχνατε — τίποτα περιττό.",en:"A ready-made CRM asks you to adapt to it. Custom software is built around the way you already work: it has only what you need, exactly where you would look for it — nothing extra."}},{q:{el:"Θα δουλεύει και στο κινητό;",en:"Will it work on mobile too?"},a:{el:"Ναι — στο κινητό και στον υπολογιστή. Στο μαγαζί, στο γραφείο ή καθ’ οδόν, βλέπετε και ενημερώνετε τα ίδια δεδομένα.",en:"Yes — on mobile and on desktop. In the shop, at the office or on the move, you see and update the same data."}},{q:{el:"Τι γίνεται με τα δεδομένα που έχω ήδη σε Excel και τετράδια;",en:"What about the data I already have in Excel and notebooks?"},a:{el:"Τα περνάμε εμείς. Δεν ξεκινάτε από λευκή σελίδα — την πρώτη μέρα, οι πελάτες και το ιστορικό σας είναι ήδη μέσα.",en:"We migrate it for you. You don't start from a blank page — on day one, your clients and history are already in."}},{q:{el:"Θα μάθει η ομάδα μου να το χρησιμοποιεί;",en:"Will my team learn to use it?"},a:{el:"Ναι — η εκπαίδευση της ομάδας σας περιλαμβάνεται. Κι επειδή το πρόγραμμα σχεδιάζεται πάνω στον τρόπο που ήδη δουλεύετε, η μετάβαση είναι πολύ πιο απλή από ένα ξένο, έτοιμο εργαλείο.",en:"Yes — training your team is included. And because the software is designed around how you already work, the transition is far simpler than with a foreign, off-the-shelf tool."}}],card:{points:[1,2],cta:{el:"Μάθετε περισσότερα",en:"Learn more"}}}],i=[{key:"wedding",title:{el:"Ιστοσελίδες Γάμου & Βάπτισης",en:"Wedding & Christening Websites"},body:{el:"Ένα link στο προσκλητήριο: εκκλησία, χάρτης, δήλωση παρουσίας — και η λίστα καλεσμένων έτοιμη στα χέρια σας.",en:"One link on the invitation: church, map, RSVP — and the guest list ready in your hands."},href:null},{key:"calculators",title:{el:"Υπολογιστές Κόστους",en:"Cost Calculators"},body:{el:"Ο επισκέπτης που ψάχνει τιμή φεύγει αν δεν τη βρει. Δώστε του μια εκτίμηση — και κερδίστε το τηλέφωνό του.",en:"A visitor looking for a price leaves if they can't find one. Give them an estimate — and win their phone number."},href:null},{key:"social",title:{el:"Διαχείριση Social Media",en:"Social Media Management"},body:{el:"Επαγγελματικά posts και συνέπεια στα προφίλ σας — χωρίς να χρειάζεται να το σκέφτεστε εσείς.",en:"Professional posts and consistency on your profiles — without you having to think about it."},href:"/diaxeirisi-social-media"}],s=[{q:{el:"Πόσο κοστίζει τελικά μια ιστοσελίδα;",en:"How much does a website actually cost?"},a:{el:"Η κατασκευή είναι δωρεάν — χωρίς προκαταβολή και χωρίς κόστος σχεδιασμού. Το μόνο που πληρώνετε είναι η φιλοξενία της σελίδας (130€ τον χρόνο ή 15€ τον μήνα), και αυτή μόνο όταν παραδοθεί το πρώτο δείγμα. Το domain name είναι δώρο. Τις αναλυτικές τιμές φιλοξενίας θα τις βρείτε στη σελίδα της Κατασκευής Ιστοσελίδων.",en:"The build is free — no deposit and no design fee. The only thing you pay is the hosting (€130 a year or €15 a month), and only once the first draft is delivered. The domain name is a gift. You will find the detailed hosting pricing on the Website Creation page."}},{q:{el:"Πόσο γρήγορα θα είναι έτοιμη;",en:"How quickly will it be ready?"},a:{el:"Μόλις λάβουμε το υλικό σας — φωτογραφίες, βασικά κείμενα, στοιχεία επικοινωνίας — παραδίδουμε το πρώτο δείγμα σε 4–10 ημέρες. Από εκεί, ο χρόνος εξαρτάται μόνο από τις αλλαγές που θα θελήσετε.",en:"Once we receive your material — photos, short texts, contact details — we deliver the first draft within 4–10 days. From there, timing depends only on the changes you want."}},{q:{el:"Τι γίνεται αν δεν μου αρέσει το αποτέλεσμα;",en:"What if I don't like the result?"},a:{el:"Το αλλάζουμε — όσες φορές χρειαστεί, χωρίς χρέωση, μέχρι να είναι ακριβώς όπως το θέλετε. Κι επειδή δεν έχετε δώσει προκαταβολή, δεν ρισκάρετε τίποτα για να δείτε το πρώτο δείγμα.",en:"We change it — as many times as needed, at no charge, until it's exactly what you want. And since there's no deposit, you risk nothing to see the first draft."}},{q:{el:"Χρειάζομαι τεχνικές γνώσεις;",en:"Do I need technical knowledge?"},a:{el:"Όχι. Αναλαμβάνουμε τα πάντα: σχεδιασμό, κατασκευή, domain, φιλοξενία, ασφάλεια και συντήρηση. Εσείς στέλνετε το υλικό σας και εγκρίνετε το αποτέλεσμα — τίποτα τεχνικό δεν περνάει από εσάς.",en:"No. We handle everything: design, build, domain, hosting, security and maintenance. You send your material and approve the result — nothing technical ever lands on you."}},{q:{el:"Μπορώ να αλλάξω πράγματα στη σελίδα αργότερα;",en:"Can I change things on the site later?"},a:{el:"Ναι. Μας στέλνετε το αίτημά σας και ολοκληρώνουμε τις αλλαγές εντός 3 εργάσιμων ημερών. Κι αν θέλετε να αλλάζετε μόνοι σας κείμενα και εικόνες, προσθέτουμε στη σελίδα σας πίνακα διαχείρισης (admin panel).",en:"Yes. You send us your request and we complete the changes within 3 working days. And if you want to edit texts and images yourself, we add an admin panel to your site."}}];function a(e){return t.find(o=>o.slug===e)}}}]);